import {
  Controller,
  Post,
  Req,
  UseGuards,
  UseInterceptors,
  UploadedFile,
  BadRequestException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { memoryStorage } from 'multer';
import { v4 as uuid } from 'uuid';
import { Request } from 'express';
import { AuthGuard } from '../auth/auth.guard';
import { StorageService } from '../storage/storage.service';
import { UploadsRepository } from './uploads.repository';

const MAX_FILE_SIZE_BYTES = 25 * 1024 * 1024; // 25 MB
const ALLOWED_MIME_TYPES = new Set(['image/png', 'image/jpeg', 'application/pdf']);

function sanitizeFileName(name: string): string {
  return name.replace(/[^a-zA-Z0-9._-]/g, '_');
}

@UseGuards(AuthGuard)
@Controller('uploads')
export class UploadController {
  constructor(
    private readonly storageService: StorageService,
    private readonly uploadsRepository: UploadsRepository,
  ) {}

  // The entire file is buffered into `file.buffer` in process memory
  // BEFORE this handler body ever runs — memory cost == file size, per request.
  @Post()
  @UseInterceptors(
    FileInterceptor('file', {
      storage: memoryStorage(),
      limits: { fileSize: MAX_FILE_SIZE_BYTES },
    }),
  )
  async uploadFile(
    @UploadedFile() file: Express.Multer.File,
    @Req() req: Request & { user: { id: string } },
  ): Promise<{ url: string }> {
    if (!file) {
      throw new BadRequestException('No file provided');
    }

    if (!ALLOWED_MIME_TYPES.has(file.mimetype)) {
      throw new BadRequestException(`Unsupported content-type: ${file.mimetype}`);
    }

    const ownerId = req.user.id;
    const key = `${uuid()}-${sanitizeFileName(file.originalname)}`;

    // Second network hop: the full buffer is streamed server -> storage.
    // The request/connection stays open for this entire transfer.
    await this.storageService.putObject(key, file.buffer, {
      contentType: file.mimetype,
    });

    const record = await this.uploadsRepository.create({
      key,
      size: file.size,
      mimetype: file.mimetype,
      ownerId,
    });

    return { url: this.storageService.getPublicUrl(record.key) };
  }
}
